INSERT INTO `posts` VALUES (1,'Trí tuệ nhân tạo thay đổi thế giới trong năm 2026','tri-tue-nhan-tao-thay-doi-the-gioi-trong-nam-2026-1',NULL,NULL,NULL,NULL,0,'Năm 2026 chứng kiến sự bùng nổ chưa từng có của trí tuệ nhân tạo.\n\nCác mô hình ngôn ngữ lớn đã được tích hợp vào hầu hết các lĩnh vực quan trọng của cuộc sống, từ y tế, giáo dục đến sản xuất công nghiệp.\n\nViệt Nam cũng không nằm ngoài xu thế này khi nhiều doanh nghiệp công nghệ trong nước đã ứng dụng AI vào quy trình vận hành.\n\nTheo các chuyên gia, đây chỉ là khởi đầu của một kỷ nguyên mới mà con người và máy móc cùng cộng tác.',NULL,'https://images.unsplash.com/photo-1677442135703-1787eea5ce01?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80',NULL,'published',42,3.00,1,2,'2026-04-13 07:43:03','2026-04-16 09:50:52'),(2,'Thị trường chứng khoán Việt Nam vượt mốc 1.400 điểm','thi-truong-chung-khoan-viet-nam-1400-diem',NULL,NULL,NULL,NULL,0,'Chỉ số VN-Index đã vượt mốc 1.400 điểm trong phiên giao dịch sáng nay.\n\nĐây là lần đầu tiên trong lịch sử thị trường chứng khoán Việt Nam đạt được ngưỡng này.\n\nNhà đầu tư nước ngoài tiếp tục mua ròng với giá trị hơn 2.500 tỷ đồng trong tuần qua.\n\nGiới phân tích cho rằng đà tăng có thể tiếp tục nếu dòng tiền nội địa được duy trì.',NULL,'https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',NULL,'published',23,NULL,2,3,'2026-04-13 07:43:03','2026-04-13 10:44:31'),(3,'Tuyển Việt Nam chuẩn bị cho vòng loại World Cup 2026','tuyen-viet-nam-world-cup-2026',NULL,NULL,NULL,NULL,0,'Đội tuyển bóng đá quốc gia Việt Nam đang trong giai đoạn chuẩn bị tích cực.\n\nHLV trưởng đã triệu tập danh sách 25 cầu thủ cho đợt tập trung tháng này.\n\nNhiều gương mặt trẻ từ V.League được gọi lên thử nghiệm.\n\nMục tiêu của đội là giành ít nhất 2 trận thắng trong vòng loại tiếp theo.',NULL,'https://images.unsplash.com/photo-1574629810360-7efbbe195018?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',NULL,'published',26,NULL,3,3,'2026-04-13 07:43:03','2026-04-13 10:36:16'),(4,'Phim Việt đạt doanh thu kỷ lục 300 tỷ đồng','phim-viet-doanh-thu-300-ty-dong',NULL,NULL,NULL,NULL,0,'Một bộ phim điện ảnh Việt Nam vừa cán mốc 300 tỷ đồng doanh thu phòng vé.\n\nĐây là kỷ lục mới của điện ảnh Việt, vượt qua các bộ phim nước ngoài đang chiếu cùng thời điểm.\n\nBộ phim khai thác chủ đề gia đình và được đầu tư về mặt kỹ xảo điện ảnh.\n\nNhà sản xuất cho biết đang lên kế hoạch phần 2 dựa trên phản hồi tích cực từ khán giả.',NULL,'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',NULL,'published',11,NULL,4,3,'2026-04-13 07:43:03','2026-04-13 10:25:29'),(5,'Bộ Y tế khuyến cáo người dân tiêm vaccine cúm mùa','bo-y-te-tiem-vaccine-cum-mua',NULL,NULL,NULL,NULL,0,'Bộ Y tế vừa phát đi khuyến cáo người dân nên chủ động tiêm phòng cúm mùa.\n\nVaccine cúm năm nay được cập nhật để phù hợp với các chủng virus đang lưu hành.\n\nCác nhóm nguy cơ cao như người cao tuổi, trẻ em và phụ nữ có thai cần được ưu tiên.\n\nVắc-xin hiện có tại các cơ sở y tế và các trung tâm tiêm chủng trên toàn quốc.',NULL,'https://images.unsplash.com/photo-1559757148-5c350d0d3c56?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',NULL,'published',5,NULL,5,3,'2026-04-13 07:43:03','2026-04-13 10:25:29'),(7,'Ví điện tử và xu hướng thanh toán một chạm tăng trưởng bùng nổ','vi-dien-tu-va-xu-huong-thanh-toan-mot-cham-tang-truong-bung-no-592826',NULL,NULL,NULL,NULL,0,'\nĐây là nội dung bài viết mẫu được tự động tạo ra nhằm mục đích kiểm thử hệ thống giao diện và trải nghiệm người dùng (UI/UX).\n\n\nTrong thực tế, nội dung này sẽ được thay thế bằng bài báo thật do các biên tập viên soạn thảo cẩn thận. Tuy nhiên trong môi trường thử nghiệm, chúng tôi đưa vào các đoạn văn bản giữ chỗ để bạn có thể xem bố cục, font chữ, độ dãn cách dòng và hiển thị hình ảnh có hoạt động ổn định hay không.\n\n\n\n--- Phân Tích Chuyên Sâu ---\n\n\nMột bài viết tốt không chỉ chứa thông tin bề mặt mà còn có các đoạn phân tích kỹ lưỡng, trích dẫn số liệu cụ thể và đi sâu vào cốt lõi vấn đề để mang tới người đọc góc nhìn đa chiều.\n\n\n',NULL,'https://picsum.photos/1200/800?random=7330',NULL,'published',5015,NULL,1,NULL,'2026-04-16 11:09:25','2026-04-18 09:23:54'),(8,'Apple dự kiến tung ra dòng tai nghe không dây khử ồn thế hệ mới','apple-du-kien-tung-ra-dong-tai-nghe-khong-day-khu-on-the-he-moi-592845',NULL,NULL,NULL,NULL,0,'\nĐây là nội dung bài viết mẫu được tự động tạo ra nhằm mục đích kiểm thử hệ thống giao diện và trải nghiệm người dùng (UI/UX).\n\n\nTrong thực tế, nội dung này sẽ được thay thế bằng bài báo thật do các biên tập viên soạn thảo cẩn thận. Tuy nhiên trong môi trường thử nghiệm, chúng tôi đưa vào các đoạn văn bản giữ chỗ để bạn có thể xem bố cục, font chữ, độ dãn cách dòng và hiển thị hình ảnh có hoạt động ổn định hay không.\n\n\n\n--- Phân Tích Chuyên Sâu ---\n\n\nMột bài viết tốt không chỉ chứa thông tin bề mặt mà còn có các đoạn phân tích kỹ lưỡng, trích dẫn số liệu cụ thể và đi sâu vào cốt lõi vấn đề để mang tới người đọc góc nhìn đa chiều.\n\n\n',NULL,'https://picsum.photos/1200/800?random=8025',NULL,'published',4054,NULL,1,NULL,'2026-04-16 11:09:25','2026-04-16 13:17:00'),(9,'AI của Google và OpenAI đại chiến tại sự kiện triển lãm lớn nhất năm','ai-cua-google-va-openai-dai-chien-tai-su-kien-trien-lam-lon-nhat-nam-592889',NULL,NULL,NULL,NULL,0,'\nĐây là nội dung bài viết mẫu được tự động tạo ra nhằm mục đích kiểm thử hệ thống giao diện và trải nghiệm người dùng (UI/UX).\n\n\nTrong thực tế, nội dung này sẽ được thay thế bằng bài báo thật do các biên tập viên soạn thảo cẩn thận. Tuy nhiên trong môi trường thử nghiệm, chúng tôi đưa vào các đoạn văn bản giữ chỗ để bạn có thể xem bố cục, font chữ, độ dãn cách dòng và hiển thị hình ảnh có hoạt động ổn định hay không.\n\n\n\n--- Phân Tích Chuyên Sâu ---\n\n\nMột bài viết tốt không chỉ chứa thông tin bề mặt mà còn có các đoạn phân tích kỹ lưỡng, trích dẫn số liệu cụ thể và đi sâu vào cốt lõi vấn đề để mang tới người đọc góc nhìn đ